cat tsconfig.json vitest.config.ts && cat > src/claim-office.spec.ts <<'EOF'
import { describe, it, expect } from "vitest";
import { runScenario } from "./claim-office.js";

describe("MHPCO Claim Office", () => {
  describe("quote: base premiums", () => {
    it.todo("empty item list → premium 5 G (only the processing fee)");
    it.todo("single sword (newcomer, first quote) → 100 base + 10 first insurance + 5 fee = 115 G");
    it.todo("single amulet → 60 base + 6 first insurance + 5 fee = 71 G");
    it.todo("single staff → 80 base + 8 first insurance + 5 fee = 93 G");
    it.todo("single potion → 40 base + 4 first insurance + 5 fee = 49 G");
    it.todo("2 runes → 50 G base premium (55 + 5 fee = 60 G)");
    it.todo("3 runes → 60 G base premium, block applies (66 + 5 fee = 71 G)");
    it.todo("4 runes → 100 G base premium, no block (110 + 5 fee = 115 G)");
    it.todo("7 runes → 175 G base premium (192.5 + 5 → rounded up to 198 G)");
    it.todo("2 runes + 1 moonstone → 75 G base premium, no block across types (82.5 + 5 → 88 G)");
    it.todo("3 runes + 3 moonstones → 120 G base premium, two separate blocks (132 + 5 = 137 G)");
  });

  describe("quote: premium modifiers", () => {
    it.todo("cursed sword, newcomer → 100 + 50 curse + 10 first insurance + 5 fee = 165 G");
    it.todo("sword with enchantment 5 → high-enchantment surcharge applies (100 + 30 + 13 + 5 = 148 G)");
    it.todo("sword with enchantment 4 → no high-enchantment surcharge (115 G)");
    it.todo("cursed sword with enchantment 5 → both surcharges apply (100 + 50 + 30 + 18 + 5 = 203 G)");
    it.todo("customer with exactly 2 years → loyalty discount applies (100 − 20 + 10 + 5 = 95 G)");
    it.todo("customer with 1 year → no loyalty discount (115 G)");
    it.todo("second quote in scenario → 15 % follow-up discount (100 + 10 − 15 + 5 = 100 G)");
    it.todo("cursed sword + plain amulet → curse surcharge on sword only: 160 + 50 = 210, + 21 first insurance + 5 fee = 236 G");
    it.todo("long-standing customer's second contract, cursed sword enchantment 7 → 160 G");
    it.todo("premium yielding 197.5 G is rounded up to 198 G");
  });

  describe("claim: standard reimbursement", () => {
    it.todo("regular sword (steel, enchantment 3), damage 500 G → payout 400 G");
    it.todo("rune damage 200 G → payout 100 G (no special clause for components)");
    it.todo("claim result includes remainingCap (sword: cap 2000 − 400 = 1600)");
  });

  describe("claim: special clauses", () => {
    it.todo("steel sword enchantment 9, damage 1000 G → payout 400 G (50 % rule, then deductible)");
    it.todo("dragon sword enchantment 5, damage 800 G → payout 700 G (full reimbursement, then deductible)");
    it.todo("dragon sword enchantment 9, damage 1000 G → payout 400 G (50 % rule wins)");
    it.todo("dragon sword exactly enchantment 8, damage 1000 G → payout 400 G");
  });

  describe("claim: deductible per damage event", () => {
    it.todo("dragon attack damages sword (500) and amulet (300) → payout 600 G (deductible once per damaged item)");
    it.todo("two swords insured, two sword damages → each treated separately with its own deductible");
  });

  describe("claim: cap", () => {
    it.todo("sword + amulet → insurance sum 1600, cap 3200 (remainingCap after 500 damage = 2800)");
    it.todo("cursed sword → cap 2000 based on unmodified insurance value");
    it.todo("sword + 3 runes → insurance sum 1750, cap 3500 (block does not affect insurance sum)");
    it.todo("two swords → insurance sum 2000, cap 4000");
    it.todo("two successive 1500 G claims on a sword → 1400 (cap 600 left), then 600 (cap 0 left)");
    it.todo("payout yielding 350.5 G is rounded down to 350 G");
  });

  describe("errors", () => {
    it.todo("quote with unknown item type (broomstick) → throws");
    it.todo("claim damage for item not in the policy (amulet when only sword insured) → throws");
    it.todo("claim damage with unknown item type → throws");
    it.todo("more sword damages than swords insured → throws");
    it.todo("claim damage with negative amount → throws");
  });
});
EOF
pnpm test 2>&1 | tail -15

