export type Scenario = { customer: { yearsWithMHPCO: number }; steps: Step[] };

export type Result = { premium: number } | { payout: number; remainingCap: number };

const PROCESSING_FEE = 5;
const SWORD_BASE_PREMIUM = 100;
const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;

const withFirstInsuranceSurcharge = (basePremium: number): number =>
  basePremium + basePremium * FIRST_INSURANCE_SURCHARGE_RATE;

export const runScenario = (scenario: Scenario): { results: Result[] } => {
  const step = scenario.steps[0];
  const basePremium =
    step.op === "quote" && step.items.length === 0 ? 0 : SWORD_BASE_PREMIUM;
  const premium = withFirstInsuranceSurcharge(basePremium) + PROCESSING_FEE;
  return { results: [{ premium }] };
};
