const PROCESSING_FEE = 5;
const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
};
const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;

const sumBasePremiums = (items: Item[]): number =>
  items.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);

const withFirstInsuranceSurcharge = (basePremium: number): number =>
  basePremium + basePremium * FIRST_INSURANCE_SURCHARGE_RATE;

export const runScenario = (scenario: Scenario): { results: Result[] } => {
  const step = scenario.steps[0];
  const items = step.op === "quote" ? step.items : [];
  const premium = withFirstInsuranceSurcharge(sumBasePremiums(items)) + PROCESSING_FEE;
  return { results: [{ premium }] };
};

