const processClaim = (insuredItems: Item[], damages: Damage[]): Result => {
  const payout = claimPayout(insuredItems, damages);
  return { payout, remainingCap: payoutCap(insuredItems) - payout };
};

// Every contract after the customer's first in a scenario is a follow-up contract.
const isFollowUpContract = (stepIndex: number): boolean => stepIndex > 0;

export const runScenario = (scenario: Scenario): { results: Result[] } => {
  const results = scenario.steps.map((step, index): Result => {
    if (step.op === "claim") {
      return processClaim(insuredItemsOf(scenario.steps[step.policy]), step.incident.damages);
    }
    const customer: CustomerContext = {
      yearsWithMHPCO: scenario.customer.yearsWithMHPCO,
      isFollowUpContract: isFollowUpContract(index),
    };
    return { premium: quotePremium(step.items, customer) };
  });
  return { results };
};

